            </button>
            <button
              onClick={confirmClear}
              style={{
                padding: "10px 24px",
                fontSize: "1rem",
                borderRadius: "24px",
                border: "none",
                backgroundColor: "#e53935",
                color: "#fff",
                cursor: "pointer",
                fontWeight: "600",
                minWidth: "100px"
              }}
            >
              Yes, Clear
            </button>
          </div>
        </div>
      </div>
    )}

    {showAlertModal && (
      <div style={{
        position: "fixed",
        top: 0,
        left: 0,
        width: "100vw",
        height: "100vh",
        backgroundColor: "rgba(0, 0, 0, 0.7)",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        zIndex: 3000
      }}>
        <div style={{
          background: "#fff",
          padding: "30px",
          borderRadius: "12px",
          boxShadow: "0 0 20px rgba(0,0,0,0.3)",
          textAlign: "center",
          maxWidth: "400px",
          width: "90%"
        }}>
          <h3 style={{ marginBottom: "20px", fontSize: "1.3rem", color: "#303036" }}>
            Notice
          </h3>
          <p style={{ marginBottom: "25px", fontSize: "1rem", lineHeight: "1.5", color: "#555" }}>
            {alertMessage}
          </p>
          
          <button
            onClick={() => setShowAlertModal(false)}
            style={{
              padding: "10px 24px",
              fontSize: "1rem",
              borderRadius: "24px",
              border: "none",
              backgroundColor: "#303036",
              color: "#fff",
              cursor: "pointer",
              fontWeight: "600",
              minWidth: "100px"
            }}
          >
            OK
          </button>
        </div>
      </div>
    )}
  </>
);
}
